export function PendingState({
  label = "{{label}}",
  stage = "{{stage}}",
  eta = "{{eta}}",
  showSpinner = {{showSpinner}},
}) {
  return (
    <div role="status" aria-live="polite" style={{ display: "flex", alignItems: "center", gap: 12, maxWidth: 320,
      padding: "12px 16px", boxSizing: "border-box", borderRadius: 10, background: "#FAF7F2",
      border: "1px solid #24143022", font: "13.5px/1.4 system-ui, sans-serif", color: "#241430" }}>
      {showSpinner && (
        <span aria-hidden="true" className="pending-spinner" style={{ width: 20, height: 20, borderRadius: "50%", border: "2.5px solid #24143022",
          borderTopColor: "#8A6FBF", flexShrink: 0 }} />
      )}
      <div>
        <p style={{ margin: 0, fontWeight: 700 }}>{label}</p>
        <p style={{ margin: "2px 0 0", textTransform: "capitalize", color: "#241430b3" }}>{stage} · ETA {eta}</p>
      </div>
      <style>{`
        @media (prefers-reduced-motion: no-preference) {
          .pending-spinner { animation: pending-react-spin .8s linear infinite; }
          @keyframes pending-react-spin { to { transform: rotate(360deg); } }
        }
      `}</style>
    </div>
  );
}
